import { Worker } from 'node:worker_threads';

function ask(worker: Worker, step: string): Promise<any> {
  return new Promise<any>((resolve: (value: any) => void): void => {
    worker.once('message', resolve);
    worker.postMessage(step);
  });
}

async function main(): Promise<void> {
  process.env.SV_C = 'parent1';
  const alive = 'setInterval(() => {}, 1000);';
  const copySource = `
    const { parentPort } = require('node:worker_threads');
    parentPort.on('message', (step) => {
      if (step === 'view') {
        parentPort.postMessage('view ' + process.env.SV_C + ' ' + Object.keys(process.env).includes('SV_C'));
      } else {
        process.env.SV_B = 'fromworker';
        parentPort.postMessage('wrote');
      }
    });
    ${alive}
  `;
  const objectSource = `
    const { parentPort } = require('node:worker_threads');
    parentPort.on('message', (step) => {
      if (step === 'view') {
        parentPort.postMessage('view ' + process.env.SV_O + ' ' + process.env.SV_C + ' ' + Object.keys(process.env).join(','));
      } else {
        process.env.SV_B = 'fromworker';
        parentPort.postMessage('wrote');
      }
    });
    ${alive}
  `;
  const w1 = new Worker(copySource, { eval: true });
  console.log('default', await ask(w1, 'view'));
  console.log('default', await ask(w1, 'write'));
  await w1.terminate();
  console.log('default after', process.env.SV_B);

  const w2 = new Worker(objectSource, { eval: true, env: { SV_O: '1' } });
  console.log('object', await ask(w2, 'view'));
  console.log('object', await ask(w2, 'write'));
  await w2.terminate();
  console.log('object after', process.env.SV_B, process.env.SV_O);

  const w3 = new Worker(copySource, { eval: true, env: process.env });
  console.log('copy-env', await ask(w3, 'view'));
  console.log('copy-env', await ask(w3, 'write'));
  await w3.terminate();
  console.log('copy-env after', process.env.SV_B);
}
